import{_ as d,o,c as t,a3 as c}from"./chunks/framework.Ch_0qWu9.js";const m=JSON.parse('{"title":"Online Solver 后端协议","description":"","frontmatter":{"sourcePath":"docs/solver-backend.zh-CN.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/solver-backend.zh-CN.md","alternateUrl":"/TCSExam/docs/solver-backend/","alternateAnchors":{"online-solver-后端协议":"online-solver-backend-protocol","部署范围":"deployment-scope","凭证与尝试标识":"credentials-and-attempt-identity","会话接口":"session-interface","镜像与部署":"images-and-deployment","online-solver-backend-protocol":"online-solver-backend-protocol","deployment-scope":"deployment-scope","credentials-and-attempt-identity":"credentials-and-attempt-identity","session-interface":"session-interface","images-and-deployment":"images-and-deployment"}},"headers":[],"relativePath":"zh/solver-backend/index.md","filePath":"zh/solver-backend/index.md"}'),a={name:"zh/solver-backend/index.md"};function s(n,e,i,r,l,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<p><a id="online-solver-backend-protocol"></a></p><h1 id="online-solver-后端协议" tabindex="-1">Online Solver 后端协议 <a class="header-anchor" href="#online-solver-后端协议" aria-label="Permalink to &quot;Online Solver 后端协议&quot;">​</a></h1><p>本参考文档描述 Online Solver 客户端使用的 HTTP 接口。 面向服务运维人员和实现兼容适配器的开发者。</p><p><a id="deployment-scope"></a></p><h2 id="部署范围" tabindex="-1">部署范围 <a class="header-anchor" href="#部署范围" aria-label="Permalink to &quot;部署范围&quot;">​</a></h2><ol><li><p>用 <code>tcsexam build</code> 准备选定的开发镜像和判分镜像。</p></li><li><p>按照 <a href="/TCSExam/docs/zh/backend/docker/">Docker 部署指南</a>或使用 <a href="/TCSExam/docs/zh/backend/service/#writing-a-platform-adapter">自定义平台适配器</a>配置凭证并启动服务。</p></li><li><p>针对所选部署配置 <code>prepare</code>、<code>doctor</code> 和 <code>run</code>：</p><ul><li>Docker 部署：提供生成的 <code>--backend-plan PATH</code>，其中包含服务地址和选定题目的工作容器规划。</li><li>外部服务：传入 <code>--judge-url URL</code>，或将 <code>TCSEXAM_BASE_URL</code> 设置为题目容器可以访问的地址。 生成的 Docker 规划可选；未提供时，启动器会使用选择记录中各题的标准工作容器数量、 资源以及 <code>standard_client_timing</code> 下记录的时间设置。服务必须提供这些资源并遵守题目预算。</li></ul></li><li><p>在作业输出中检查提交记录和最终结果。</p></li></ol><p>客户端为 <code>tasks/solver/online/&lt;task&gt;/environment/submit.sh</code> 和 <code>tasks/solver/online/&lt;task&gt;/tests/fetch_final.py</code>。它们使用题目声明的实例集、时间预算和计分规则。</p><p><a id="credentials-and-attempt-identity"></a></p><h2 id="凭证与尝试标识" tabindex="-1">凭证与尝试标识 <a class="header-anchor" href="#凭证与尝试标识" aria-label="Permalink to &quot;凭证与尝试标识&quot;">​</a></h2><p>所有请求均使用身份认证。归档凭证仅提供给验证器。请求头名称不区分大小写。</p><p>读法说明：每行给出一个 HTTP 请求头及其值。</p><table tabindex="0"><thead><tr><th>HTTP 请求头</th><th>值</th></tr></thead><tbody><tr><td><code>X-TCSEXAM-Token-Id</code></td><td><code>TCSEXAM_TOKEN_ID</code></td></tr><tr><td><code>X-TCSEXAM-Token-Secret</code></td><td><code>TCSEXAM_TOKEN_SECRET</code></td></tr><tr><td><code>X-TCSEXAM-Client-Id</code></td><td>本次题目尝试的稳定标识</td></tr><tr><td><code>X-TCSEXAM-Run-Id</code></td><td>同一个题目尝试标识</td></tr><tr><td><code>X-TCSEXAM-Agent-Name</code></td><td>可选的 <code>TCSEXAM_AGENT_NAME</code></td></tr><tr><td><code>X-TCSEXAM-Archive-Token</code></td><td>来自 <code>/tests/archive_token</code>、仅供验证器使用的凭证</td></tr></tbody></table><p>将 <code>TCSEXAM_RUN_ID</code> 设为每次尝试唯一且稳定的标识。未设置时，客户端使用容器主机名。 后端必须隔离共用出口地址的不同尝试。凭证和归档内容的访问范围必须限定在所属尝试内； 模型不得获取归档凭证。</p><p>随附服务会检查每个会话声明的 Run-Id，以区分共用服务凭证且相互配合的调用方。 Run-Id 是调用方提供的标签；需要防止蓄意冒充的部署还须为每次尝试提供独立认证的凭证。 参见服务的<a href="/TCSExam/docs/zh/backend/service/#security-boundaries">安全边界</a>。</p><p>前台请求、后台保活请求、终判和审计下载应使用相同的请求头名称。TCSEXAM 接口始终使用这一命名空间。 创建隐藏会话、任何携带 <code>judge_payload</code> 的创建操作，以及所有会话列表和核对查询， 除服务令牌对外还必须提供归档请求头。在这些创建和列表操作中，归档凭证缺失、错误或未配置均返回 403。 不携带 <code>judge_payload</code> 的公开自测创建、状态查询、提交和结果轮询仅使用服务令牌对。 归档请求头只发送到创建、列表以及归档和载荷服务端点，不得经过求解器提交转发接口传入判分工作容器。</p><p>使用 TCSExam 启动器将凭证传入 agent 和验证器容器。自定义启动器需填充题目的 <code>${TCSEXAM_*}</code> 占位符，并保留凭证仅放置于验证器的要求。</p><p><a id="session-interface"></a></p><h2 id="会话接口" tabindex="-1">会话接口 <a class="header-anchor" href="#会话接口" aria-label="Permalink to &quot;会话接口&quot;">​</a></h2><p>以下路径均相对于 <code>TCSEXAM_BASE_URL</code>。现有客户端定义每道题的确切行为；下表展示它们共用的接口。</p><p>读法说明：每行列出一种方法和路径及其行为。</p><table tabindex="0"><thead><tr><th>方法和路径</th><th>行为</th></tr></thead><tbody><tr><td><code>POST /v1/judge/sessions</code></td><td>接收 <code>judge_image</code>、<code>ttl</code>、<code>n_shards</code>、<code>resources</code>，以及可选的 <code>instance_set</code> 和 <code>judge_payload</code>；返回 <code>session_id</code>。公开自测请求 <code>public</code>，且必须存在精确匹配的 <code>public_image_map</code> 条目。不带载荷时只需服务身份认证。省略实例集时默认为 <code>hidden</code>；创建隐藏会话和所有携带 <code>judge_payload</code> 的创建操作还须提供归档请求头。</td></tr><tr><td><code>GET /v1/judge/sessions</code></td><td>列出活跃会话和最近销毁的会话。需要归档请求头；下列 <code>session_ids</code> 和 <code>client_ip</code> 查询形式也适用。</td></tr><tr><td><code>GET /v1/judge/sessions/{id}</code></td><td>报告就绪状态和失败情况。资源准备必须完成后才能开始判分。</td></tr><tr><td><code>POST /v1/judge/sessions/{id}/submit</code></td><td>接收 <code>Content-Type: application/gzip</code> 的原始 tar.gz；接受后返回整数 <code>submission</code>。不要通过此转发接口发送归档请求头。</td></tr><tr><td><code>GET /v1/judge/sessions/{id}/submissions</code></td><td>返回 <code>submissions</code>，每项包含 <code>submission</code>、<code>status</code> 和逐实例 <code>records</code>。未完成提交使用 <code>running</code> 状态。</td></tr><tr><td><code>GET /v1/judge/sessions/{id}/archive</code></td><td>需要归档请求头，返回各分片的原始记录，包括 <code>instance_set</code>、<code>n_shards</code>、<code>shard_payloads</code> 和 <code>failed_shards</code>。</td></tr><tr><td><code>GET /v1/judge/sessions?session_ids=a,b</code></td><td>需要归档请求头。返回各会话的隐藏提交计数 <code>submissions</code>、<code>public_submissions</code> 和 <code>present</code>；资源释放后仍保留计数。</td></tr><tr><td><code>DELETE /v1/judge/sessions/{id}</code></td><td>释放工作容器，同时保留验证所需的计数和记录。</td></tr></tbody></table><p>可选审计端点 <code>GET /v1/judge/sessions/{id}/payload/submissions</code> 和 <code>GET /v1/judge/sessions/{id}/payload/submissions/{seq}</code> 分别列出提交编号和返回原始上传的 tar 字节。 它们使用归档请求头。可选载荷不可用会单独记录，与判分失败分开处理。 旧版运维查询 <code>GET /v1/judge/sessions?client_ip=self</code> 属于可选遥测，同样需要归档请求头； 它不得用于决定一次尝试的分数或提交额度。</p><p>提交在接受时计数一次。HTTP 503 表示提交尚未被接受，可以重试。 上传连接断开且是否接受不明确时，不得盲目重试。当前验证器将 <code>/submit</code> 的 HTTP 429 解释为触及提交次数上限，因此后端不得用此响应表示普通工作容器拥堵。 HTTP 410 或 <code>error_class=terminal</code> 表示会话永久不可用。</p><p>保留每个实例的目标值、合法性和状态，包括未计入某项分数均值的实例。 基础设施失败必须与有效零分区分。保留各题的时间池、证书检查、预算、历史选择规则以及公开与隐藏数据的隔离。</p><p><a id="images-and-deployment"></a></p><h2 id="镜像与部署" tabindex="-1">镜像与部署 <a class="header-anchor" href="#镜像与部署" aria-label="Permalink to &quot;镜像与部署&quot;">​</a></h2><p>创建公开会话时，使用精确匹配的 <code>public_image_map</code> 键，将请求的判分镜像映射为仅含公开数据的工作镜像。 缺少条目时，在创建任何工作容器之前返回 HTTP 403。创建隐藏会话使用所请求的隐藏镜像。</p><p>用 <code>tcsexam build</code> 准备镜像，或提供包含不可变后端镜像分配的外部清单。 注册公开镜像前，按照<a href="/TCSExam/docs/zh/backend/public-images/">公开镜像准备</a>检查输入和保留的镜像层。 然后配置映射，并通过 <a href="/TCSExam/docs/zh/backend/docker/">Docker 指南</a>启动服务。</p>',28)])])}const u=d(a,[["render",s]]);export{m as __pageData,u as default};
